            t["decisions"] += 1
            t["leads"] += int(lead); g["leads"] += int(lead)
            t["leads_gt7"] += int(lead and h[MAXH] > 7)
            if lead:
                t["leads_by_played_kind"][played_kind] += 1
            if h[0] == FALLBACK_SCHEMA:
                if p[1:8] != [None] * 7:
                    refuse(f"sc8p on a fallback record: {w} carries probe fields {p!r}")
